package com.ecopulse.controller; import com.ecopulse.dto.AuthDtos; import com.ecopulse.service.AuthService; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/api/auth") public class AuthController { private final AuthService service; public AuthController(AuthService s){service=s;} @PostMapping("/login") public AuthDtos.AuthResponse login(@RequestBody AuthDtos.Login req){return service.login(req);} }
